private static function token_match( string $selector_part, string $above ): bool {
	if ( $selector_part === $above ) {
		return true;
	}
	$pattern = '/(?:^|[.\"\'#\(\[\s>+~])' . preg_quote( ltrim( $above, '.' ), '/' ) . '(?=[\.#:\s\[>+~\)]|$)/i';
	return (bool) preg_match( $pattern, $selector_part, $m ) && $m[0] === $above;
}

